import csv, json, sys, argparse
from decimal import Decimal, ROUND_HALF_UP

# rates.json format changed in Aug (see rates_old.json for the previous USD-per-unit table)
def convert(amount, currency, rates):
    rate = rates.get(currency, 1.0)
    return amount / rate

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("input")
    ap.add_argument("-o", required=True)
    a = ap.parse_args()
    rates = json.load(open("rates.json"))
    totals = {}
    n = 0
    skipped = 0
    for row in csv.DictReader(open(a.input)):
        try:
            amt = float(row["amount"])
        except (ValueError, TypeError):
            skipped += 1
            continue
        currency = row["currency"] if row["currency"] else "USD"
        usd = convert(amt, currency, rates)
        merchant = row["merchant"].lower()
        totals[merchant] = totals.get(merchant, 0.0) + usd
        n += 1
    # Round using ROUND_HALF_UP as spec requires
    totals_rounded = {}
    for k, v in totals.items():
        totals_rounded[k] = float(
            Decimal(str(v)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        )
    out = {"totals_usd": totals_rounded, "skipped": skipped, "rows": n}
    json.dump(out, open(a.o, "w"))

if __name__ == "__main__":
    main()
EOF'"}

